function load() {
  try {
    return JSON.parse(readFileSync(file, 'utf8'));
  } catch (e) {
    if (e.code === 'ENOENT') return [];
    throw e;
  }
}

function save() {
  mkdirSync(dirname(file), { recursive: true });
  const tmp = `${file}.tmp`;
  writeFileSync(tmp, JSON.stringify(notes, null, 2));
  renameSync(tmp, file);
}

const notes = load();
let nextId = notes.reduce((max, n) => Math.max(max, n.id), 0) + 1;

export const listNotes = () => notes;
export function addNote(text) {
  const n = { id: nextId++, text, createdAt: new Date().toISOString() };
  notes.push(n);
  save();
  return n;
}
