import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const file = join(mkdtempSync(join(tmpdir(), 'notes-')), 'notes.json');
process.env.NOTES_FILE = file;
const { addNote, listNotes, deleteNote } = await import('../src/store.js');

test('add and delete', () => {
  const n = addNote('hi');
  assert.equal(listNotes().length, 1);
  assert.equal(JSON.parse(readFileSync(file, 'utf8')).length, 1);
  assert.ok(deleteNote(n.id));
  assert.equal(listNotes().length, 0);
  assert.equal(JSON.parse(readFileSync(file, 'utf8')).length, 0);
});

test('notes survive reload', async () => {
  const n = addNote('persist me');
  const reloaded = await import('../src/store.js?reload');
  assert.deepEqual(reloaded.listNotes(), [n]);
  assert.equal(reloaded.addNote('next').id, n.id + 1);
});

